mapper.codeEditorJavascript:
const MONTHS=['ינואר','פברואר','מרץ','אפריל','מאי','יוני','יולי','אוגוסט','ספטמבר','אוקטובר','נובמבר','דצמבר'];
const arr=v=>{ if(typeof v==='string'){ try{return JSON.parse(v);}catch(e){return [];} } return Array.isArray(v)?v:[]; };
const titles=arr(input.sheets).map(s=>String(((s||{}).properties||{}).title||'').trim());
const nowIL=new Date(new Date().toLocaleString('en-US',{timeZone:'Asia/Jerusalem'}));
const tabs=[];
// RULE (Yardiv 16/11/2026): the selling rep is looked up in the דוח מכר up to 3 months back (current + 2 previous months). Do not remove.
for(const off of [0,-1,-2]){ const d=new Date(nowIL.getFullYear(),nowIL.getMonth()+off,1); const t=MONTHS[d.getMonth()]+' '+d.getFullYear(); if(titles.includes(t)) tabs.push(t); }
const q=s=>"'"+s+"'";
const filters=tabs.length? tabs.map(t=>({a1Range:q(t)+'!A1:H2000'})) : [{a1Range:q('הגדרות')+'!A1:A1'}];
return {tabs: tabs.join(', '), readBody: JSON.stringify({dataFilters:filters, valueRenderOption:'FORMATTED_VALUE'})};

const digits=s=>String(s==null?'':s).replace(/\D/g,'');
const norm=s=>String(s==null?'':s).replace(/\s+/g,' ').trim();
const arr=v=>{ if(typeof v==='string'){ try{return JSON.parse(v);}catch(e){return [];} } return Array.isArray(v)?v:[]; };
const text=norm(input.text).slice(0,500);
const phone=digits(input.phone);
const local='0'+phone.replace(/^972/,'');
const key=phone.slice(-9);
const rating=norm(input.rating);
const hasRec=norm(input.recPhone)!=='';
let recent=false; { const ms=norm(input.sentAt).match(/(\d{4})-(\d{2})-(\d{2})/); if(ms){ const nowIL=new Date(new Date().toLocaleString('en-US',{timeZone:'Asia/Jerusalem'})); recent=(nowIL-new Date(+ms[1],+ms[2]-1,+ms[3]))/86400000<=8; } }
const handled = hasRec && ((rating==='1'||rating==='2') || (recent && rating===''));
// RULE (Yardiv 16/11/2026): service/internet complaints after install (e.g. 'בחדר אין לילד אינטרנט בכלל') count as dissatisfied and go to the selling rep, to prevent disconnects. Do not remove.
const kw=/(תחזור|תחזרו|תחזרי|חוזר אלי|חוזרת אלי|חוזרים אלי|תתקשר|תתקשרו|תתקשרי|אפשר לדבר|לדבר איתך|לדבר איתכם|לדבר בטלפון|תלונ|לא מרוצ|מאוכזב|אכזב|תקל|הבטח|לא נכון|שקר|הטעו|הטעית|מטעים|מתנתק|התנתק|לנתק|לעזוב|עוזב|שוקל|לבטל|ביטול|מבטל|כסף|חיוב|חייב|שלא עולה|לא אמרת|אמרת לי|רמית|נוכל|עבדתם עלי|לא התקינו|לא הגיע|לא עובד|בעיה|נמאס|מעצבן|זועבה|גרוע|מתלונן|דחוף|אין אינטרנט|אין לו אינטרנט|אין לה אינטרנט|אין לילד אינטרנט|אינטרנט לא|האינטרנט לא|אינטרנט חלש|אין קליטה|לא קולט|איטי|נופל|קופץ|נתקע|לא מתחבר|אין שידור|אין ערוצים|חלש|ראוטר|נתב|מגדיל טווח|וויפי|ווי פי|wifi)/i;
const greet=/^(היי|הי|שלום|אהלן|הלו|תודה|תודה רבה|תודה לך|ok|אוקי|אוקיי|כן|בסדר|👍|🙏|❤️|😊)[\s!.,?🙏😊👍❤️]*$/i;
const match0=text.length>=2 && kw.test(text) && !greet.test(text);
const HEB_D=['ראשון','שני','שלישי','רביעי','חמישי','שישי','שבת'], HEB_M=['ינואר','פברואר','מרץ','אפריל','מאי','יוני','יולי','אוגוסט','ספטמבר','אוקטובר','נובמבר','דצמבר'];
const nowT=new Date(new Date().toLocaleString('en-US',{timeZone:'Asia/Jerusalem'}));
const todayStr='יום '+HEB_D[nowT.getDay()]+' '+nowT.getDate()+' '+HEB_M[nowT.getMonth()]+' '+nowT.getFullYear();
const thanksOnly=/^(תודה|תודה רבה|תודה לך|תודה רבה לך|ok|אוקי|אוקיי|👍|🙏|❤️|😊|💪)[\s!.,🙏😊👍❤️💪]*$/i;
let inst=null;
if(key.length===9 && text && !thanksOnly.test(text)){
  for(const r of arr(input.today).slice(1)){ if(r && digits(r[1]).slice(-9)===key && norm(r[2])===todayStr && norm(r[5])==='כן'){ inst={name:norm(r[0]),slot:norm(r[3]),rep:norm(r[4])}; } }
}
const match=match0 || !!inst;
// בדיקת מספר כפול: אותו נייד רשום בדוח מכר על כמה לקוחות שונים
const dupNames=[];
if(key.length===9){ const seenN={}; for(const vr of arr(input.sales)){ const vals=((vr&&vr.valueRange)||vr||{}).values||[]; for(const r of vals.slice(1)){ if(r && digits(r[3]).slice(-9)===key){ const n=norm(r[2]); if(n && !seenN[n]){ seenN[n]=1; dupNames.push(n+' – '+(norm(r[7])||'בלי נציג')); } } } } }
// RULE (15/11/2026, כפילויות): מספר כפול רק אם יש שני מספרי לקוח שונים, או (כשאין מספרי לקוח בכלל) שמות בלי אף מילה משותפת. אותו לקוח עם שם קצת שונה = לא כפול. Do not remove.
let dup=dupNames.length>1;
if(dup){ const nums=new Set(), nms=[]; for(const vr of arr(input.sales)){ const vals=((vr&&vr.valueRange)||vr||{}).values||[]; for(const r of vals.slice(1)){ if(r && digits(r[3]).slice(-9)===key){ const c=digits(r[6]); if(c) nums.add(c); const n=norm(r[2]); if(n) nms.push(n); } } }
  const tk=n=>n.replace(/[^֐-׿A-Za-z0-9\s]/g,' ').split(/\s+/).filter(w=>w.length>=2);
  const disjoint=nms.some((a,i)=>nms.some((b,j)=>j>i&&!tk(a).some(w=>tk(b).includes(w))));
  dup = nums.size>=2 || disjoint; }
let cust=null;
if(match && key.length===9){
  for(const vr of arr(input.sales)){
    if(cust) break;
    const vals=((vr&&vr.valueRange)||vr||{}).values||[];
    for(const r of vals.slice(1)){ if(r && digits(r[3]).slice(-9)===key){ cust={name:norm(r[2]),inst:norm(r[4]),num:digits(r[6]),rep:norm(r[7]),phone:digits(r[3])}; } }
  }
  // RULE (15/11/2026, כפילויות): אותו לקוח בכמה שורות - לוקחים את השורה הכי מלאה (מספר לקוח 4, לשונית החודש 2, התקנה 1, נציג 1) ולא את האחרונה. במספר כפול אמיתי / שני מספרי לקוח שונים - כמו קודם. Do not remove.
  if(cust && !dup){ const curTab=HEB_M[nowT.getMonth()]+' '+nowT.getFullYear(); const sc=c=>(c.num?4:0)+(c.tab===curTab?2:0)+(c.inst?1:0)+(c.rep?1:0); let best=null, bs=-1, orig=null; const ns=new Set();
    for(const vr of arr(input.sales)){ const v=(vr&&vr.valueRange)||vr||{}; const tb=String(v.range||'').split('!')[0].replace(/^'|'$/g,''); let last=null;
      for(const r of (v.values||[]).slice(1)){ if(r && digits(r[3]).slice(-9)===key){ const c={name:norm(r[2]),inst:norm(r[4]),num:digits(r[6]),rep:norm(r[7]),phone:digits(r[3]),tab:tb}; last=c; if(c.num) ns.add(c.num); if(sc(c)>bs){ bs=sc(c); best=c; } } }
      if(!orig&&last) orig=last; }
    if(orig && best && ns.size<2 && sc(best)>sc(orig)) cust={name:best.name,inst:best.inst,num:best.num,rep:best.rep,phone:best.phone}; }
}
let repPhone='';
const rep=(inst&&inst.rep)?inst.rep:(cust?cust.rep:''); const repFirst=rep.split(' ')[0];
if(rep){
  const cand=arr(input.targets).filter(r=>r&&r[0]&&r[1]);
  let hit=cand.find(r=>norm(r[0])===rep);
  if(!hit){ const bf=cand.filter(r=>norm(r[0]).split(' ')[0]===repFirst); if(bf.length===1) hit=bf[0]; }
  if(!hit){ const sw=cand.filter(r=>norm(r[0]).startsWith(rep)||rep.startsWith(norm(r[0]))); if(sw.length===1) hit=sw[0]; }
  if(hit){ let p=digits(hit[1]); if(p.startsWith('0')) p='972'+p.slice(1); if(/^9725\d{8}$/.test(p)) repPhone=p; }
}
const custPhone=cust&&cust.phone.length>=9?('0'+cust.phone.slice(-9)):local;
const body=cust?('\nלקוח: '+(cust.name||'לא ידוע')+'\nמספר לקוח: '+(cust.num||'לא נמצא')+'\nנייד: '+custPhone+'\nהתקנה: '+(cust.inst||'')+'\nמה הלקוח כתב: "'+text+'"'):'';
// RULE (Yardiv 16/11/2026): the rep message for a dissatisfied customer always includes the instruction: call the customer, hear the complaint, ask when he is available for a call from yes customer service, and book that call for him through Speedy (Speedy = a callback service that waits in line instead of the customer; it is NOT an upgrade). Do not remove.
const tip='\n\n💡 מה לעשות: להתקשר ללקוח ולשמוע ממנו מה הבעיה, לשאול מתי נוח לו לקבל שיחה משירות הלקוחות של yes, ולתאם לו את השיחה דרך ספידי.';
const ok=!!inst || (match0 && cust && !handled);
const sendRep=!!(ok && repPhone && !dup);
const sendMgr=!!(ok && (dup || !repPhone));
const repMsg=inst ? ('🚨 דחוף – לקוח עם התקנה היום ענה להודעת הבוקר\nשם הלקוח: '+(inst.name||(cust&&cust.name)||'לא ידוע')+(cust&&cust.num?'\nמספר לקוח: '+cust.num:'')+'\nנייד הלקוח: '+custPhone+(inst.slot?'\nחלון התקנה: '+inst.slot:'')+'\nמה הלקוח כתב: "'+text+'"\nנא לחזור אליו עכשיו, לפני ההתקנה 📞\n\n⚠️ אי אפשר לענות כאן – תשובה להודעה הזאת לא מגיעה ללקוח. צריך להתקשר אליו מהנייד הפרטי או מהמוקד.') : 'לקוח שמכרת לו פנה אלינו אחרי ההתקנה ולא מרוצה. צריך לחזור אליו היום 📞'+body+(cust?('\nחשוב לדבר איתו עוד היום, שלא יגיע לניתוק.'+tip+'\n\n⚠️ אי אפשר לענות כאן – תשובה להודעה הזאת לא מגיעה ללקוח. צריך להתקשר אליו מהנייד הפרטי או מהמוקד.'):'');
const mgrMsg=dup ? ('⚠️ מספר כפול בדוח מכר – לא העברתי לנציג, כי לא ברור של מי הלקוח\nהנייד '+local+' רשום על:\n'+dupNames.join('\n')+(inst?'\n\nענו מהמספר הזה להודעת "התקנה של היום".':'')+'\nמה כתבו: "'+text+'"\n\nצריך לבדוק מי הלקוח, להעביר לנציג שלו ולתקן את הנייד בדוח.') : ('⚠️ הנציג '+(rep||'(לא ידוע)')+' כבר לא עובד / לא נמצא לו טלפון – ההודעה מגיעה אליכם במקומו\n\n'+repMsg);
return {match, inst:!!inst, todayStr, found:!!cust, dup, dupNames:dupNames.join(' | '), handled, sendRep, repPhone, repMsg, sendMgr, mgrMsg, mgr1:'972544604246', mgr2:'972504445169'};
